package in.kabadiwala.connect.integration; import org.slf4j.*; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component; @Component @ConditionalOnProperty(name="app.sms.provider",havingValue="development",matchIfMissing=true) public class DevelopmentSmsProvider implements SmsProvider {private static final Logger log=LoggerFactory.getLogger(DevelopmentSmsProvider.class);public void sendOtp(String m,String c,String l){log.warn("DEVELOPMENT OTP for {}: {}",m,c);}public boolean exposesDevelopmentCode(){return true;}}
